        containing = [ids for ids in tight_sets if aid in ids]
        common = None
        for ids in containing:
            if common is None:
                common = set(ids)
            else:
                common &= ids
        common.discard(aid)
        implies.append([aid, sorted(common)])

    return {
        "peak": [pn, pd],
        "count": count,
        "minimal": minimal_sorted,
        "implies": implies,
    }


